effect.shader:
#define iTime (0.0)
#define iResolution vec3(acScreenSize, 1.0)
#define iDate vec4(0.0, 0.0, 0.0, iTime)
#define iMouse vec4(acScreenSize * 0.5, 0.0, 0.0)
vec3 checkerBackground(vec2 p){
vec2 cell=floor(p);
float checker=mod(cell.x+cell.y,2.0);
return mix(vec3(0.16),vec3(0.32),checker);
}
const int samples = 32,
LOD = 0,
sLOD = 1;
const float sigma = float(samples) * .25;
float gaussian(vec2 i) {
return exp( -.5* dot(i/=sigma,i) ) / ( 6.28 * sigma*sigma );
}
vec4 blur(sampler2D sp, vec2 U, vec2 scale) {
vec4 O = vec4(0);
int s = samples/sLOD;
for ( int i = 0; i < samples; i++ ) { if(i >= flameSamples) break;
vec2 d = vec2(float(i)-float(flameSamples-1)*0.5,0.0) * flameRadius;
O += gaussian(d) * texture2DCv( sp, U + scale * d );
}
return O / max(O.a,0.00001);
}
void gmGeneratedMainImage(out vec4 fragColor, vec2 fragCoord) {
vec2 uv = fragCoord.xy / iResolution.xy;
vec2 scale = 1.0 / iResolution.xy;
vec3 bloom1 = blur(inputImg.texture, uv, scale).rgb * flameNearBloom;
vec3 bloom2 = blur(inputImg.texture, uv, scale*2.0).rgb * flameWideBloom;
vec3 baseCol = texture2DCv(inputImg.texture, uv).rgb;
vec3 flame = clamp(baseCol + bloom1 + bloom2, 0.0, 1.0);
vec2 centeredUV = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
vec3 bg = checkerBackground(centeredUV*flameCheckerScale);
float alpha = smoothstep(0.0, flameAlphaEdge, length(flame));
vec3 finalCol = flameChecker ? mix(bg, flame, alpha) : flame;
fragColor = vec4(finalCol,1.0);
}
void main(){
vec4 gmGenerated=vec4(0.0);
gmGeneratedMainImage(gmGenerated,acScreenNorm*acScreenSize);
vec4 gmSource=texture2DCv(inputImg.texture,acScreenNorm);
float gmAlpha=gmClip?gmSource.a:gmGenerated.a;
vec4 gmResult=vec4(gmGenerated.rgb*gmAlpha,gmAlpha);
gl_FragColor=mix(gmSource,gmResult,gmMix);
}
